        height: 40px;
        width: 80px;
        top: 60%;
        left: 20%;
      }

      .cloud-4 {
        height: 60px;
        width: 110px;
        top: 70%;
        left: 70%;
      }

      .cloud-5 {
        height: 50px;
        width: 100px;
        top: 80%;
        left: 40%;
