# Load required libraries
library(readr)
library(stringr)
# Define function to count exact matches of "artificial intelligence"
count_exact_matches <- function(file_path) {
  # Read in text file
  text <- read_file(file_path)
  # Count exact matches of "artificial intelligence"
  count <- str_count(text, "\\bartificial intelligence\\b")
  return(count)
}
# Define function to count unique words that appear in the same sentence as "artificial intelligence"
count_unique_words <- function(file_path) {
  # Read in text file
  text <- read_file(file_path)
  # Split text into sentences
  sentences <- str_split(text, "\\.(?=\\s+[A-Z])", simplify = TRUE)[,1]
  # Initialize empty list to store unique words and their frequencies
  unique_words <- list()
  # Loop through sentences
  for (sentence in sentences) {
    # Check if sentence contains "artificial intelligence"
    if (str_detect(sentence, "\\bartificial intelligence\\b")) {
      # Split sentence into words
      words <- str_split(sentence, "\\W+")
      # Loop through words
      for (word in words) {
        # Check if word is not "artificial intelligence"
        if (word != "artificial" & word != "intelligence") {
          # Add word to unique_words list and increment frequency
          if (word %in% unique_words) {
            unique_words[[word]] <- unique_words[[word]] + 1
          } else {
            unique_words[[word]] <- 1
          }
        }
      }
    }
  }
  return(unique_words)
}
# Define table of file paths
