How can I use Scala to create a desktop application that calculates the user's Body Mass Index (BMI) based on their height and weight inputs? The application should have the following features:
1. Input fields for the user's height and weight in either metric or imperial units.
2. A button that triggers the BMI calculation and displays the result.
3. A color-coded visual representation of the result, indicating whether the user is underweight, normal weight, overweight, or obese.
4. A simple design and user-friendly interface.
Here is an example Scala code that can perform the BMI calculation:
import scala.swing._
import scala.swing.event._
object BMICalculator extends SimpleSwingApplication {
  def calculateBMI(height: Double, weight: Double): Double = {
    val heightM = height / 100
    weight / (heightM * heightM)
  }
  def getBMIStatus(bmi: Double): String = {
    if (bmi < 18.5) {
      "Underweight"
    } else if (bmi < 25) {
      "Normal weight"
    } else if (bmi < 30) {
      "Overweight"
    } else {
      "Obese"
    }
  }
  def displayResult(heightInput: TextField, weightInput: TextField, resultLabel: Label): Unit = {
    val heightText = heightInput.text
    val weightText = weightInput.text
    try {
      val height = heightText.toDouble
      val weight = weightText.toDouble
      val bmi = calculateBMI(height, weight)
      val bmiStatus = getBMIStatus(bmi)
      resultLabel.foreground = bmiStatus match {
        case "Underweight" => java.awt.Color.BLUE
        case "Normal weight" => java.awt.Color.GREEN
        case "Overweight" => java.awt.Color.ORANGE
        case "Obese" => java.awt.Color.RED
      }
      resultLabel.text = s"Your BMI is ${"%.1f".format(bmi)} - $bmiStatus"
    } catch {
      case _: NumberFormatException =>
        resultLabel.foreground = java.awt.Color.RED
        resultLabel.text = "Invalid input"
    }
  }
  def top: MainFrame = new MainFrame {
    title = "BMI Calculator"
    contents = new BoxPanel(Orientation.Vertical) {
      val heightInput = new TextField()
      val weightInput = new TextField()
      val resultLabel = new Label()
      contents += new Label("Height (cm):")
      contents += heightInput
      contents += new Label("Weight (kg):")
      contents += weightInput
      contents += new Button(Action("Calculate") {
        displayResult(heightInput, weightInput, resultLabel)
      })
      contents += resultLabel
      border = Swing.EmptyBorder(10, 10, 10, 10)
    }
  }
}
