What is a Java code that can measure hand-eye coordination in sports? Can you provide an example?
Here's a sample Java code that measures hand-eye coordination using a simple game:
import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
public class HandEyeCoordinationGame extends JFrame implements ActionListener {
   private JButton button;
   private JLabel label;
   private int score;
   private Timer timer;
   private long startTime;
   public HandEyeCoordinationGame() {
      setTitle("Hand-Eye Coordination Game");
      setSize(300, 150);
      setDefaultCloseOperation(EXIT_ON_CLOSE);

      score = 0;
      startTime = System.currentTimeMillis();

      button = new JButton("Click me when I turn green!");
      button.addActionListener(this);
      label = new JLabel("Score: " + score);

      JPanel panel = new JPanel();
      panel.add(button);
      panel.add(label);
      add(panel);

      timer = new Timer(1000, new ActionListener() {
         public void actionPerformed(ActionEvent e) {
            if (Math.random() < 0.5) {
               button.setBackground(Color.RED);
            } else {
               button.setBackground(Color.GREEN);
            }
         }
      });
      timer.start();
   }
   public void actionPerformed(ActionEvent e) {
      if (button.getBackground() == Color.GREEN) {
         score++;
         label.setText("Score: " + score);
      }
   }
   public static void main(String[] args) {
      new HandEyeCoordinationGame().setVisible(true);
   }
}

