To use Yelp's API to search for bakeries within the aforementioned radius, filter for those that sell gluten-free cupcakes, and return the name and address of those with a 4-star rating or higher, you can use the Yelp Fusion API. Here is a sample code snippet in C++:
```
#include <iostream>
#include <curl/curl.h>
#include <rapidjson/document.h>
#include <rapidjson/writer.h>
#include <rapidjson/stringbuffer.h>
#include <string>
size_t write_callback(char *ptr, size_t size, size_t nmemb, std::string *userdata) {
    size_t realsize = size * nmemb;
    userdata->append(ptr, realsize);
    return realsize;
}
void search_bakeries(double lat, double lon, double radius) {
    CURL *curl;
    CURLcode res;
    std::string read_buffer;
    curl = curl_easy_init();
    if (curl) {
        std::string api_key = "YOUR_API_KEY";
        std::string url = "https://api.yelp.com/v3/businesses/search?term=bakery&latitude=" +
                          std::to_string(lat) +
                          "&longitude=" +
                          std::to_string(lon) +
                          "&radius=" +
                          std::to_string(radius) +
                          "&categories=cupcakes&attributes=gluten_free&sort_by=rating&price=1,2";
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, ("Authorization: Bearer " + api_key).c_str());
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &read_buffer);
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            std::cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res) << std::endl;
        }
        curl_easy_cleanup(curl);
    }
    rapidjson::Document document;
    document.Parse(read_buffer.c_str());
    if (document.HasParseError()) {
        std::cerr << "JSON parse error: " << document.GetParseError() << std::endl;
        return;
    }
    for (auto &business : document["businesses"].GetArray()) {
        if (business["rating"].GetDouble() >= 4.0) {
            std::cout << business["name"].GetString() << std::endl;
            std::cout << business["location"]["address1"].GetString() << std::endl;
        }
    }
}
int main() {
    const double lat = 42.048648;
    const double lon = -87.677896;
    const double radius = 5 * 1609.34; // 5 miles in meters
    search_bakeries(lat, lon, radius);
    return 0;
}
```
Note that you will need to replace "YOUR_API_KEY" with your actual Yelp API key. Also, this code snippet requires the RapidJSON library and the libcurl library to be installed.

